1	package jobs
2	
3	import (
4		"context"
5		"errors"
6		"sync"
7		"testing"
8		"time"
9	)
10	
11	func TestRunnerRunsJobs(t *testing.T) {
12		r := NewRunner(3, 10, nil)
13		r.Start()
14		var mu sync.Mutex
15		done := map[string]bool{}
16		var wg sync.WaitGroup
17		for _, name := range []string{"a", "b", "c", "d", "e"} {
18			wg.Add(1)
19			if err := r.Enqueue(Job{Name: name, Run: func(ctx context.Context) error {
20				defer wg.Done()
21				mu.Lock()
22				done[name] = true
23				mu.Unlock()
24				return nil
25			}}); err != nil {
26				t.Fatal(err)
27			}
28		}
29		finished := make(chan struct{})
30		go func() { wg.Wait(); close(finished) }()
31		select {
32		case <-finished:
33		case <-time.After(5 * time.Second):
34			t.Fatal("jobs did not run")
35		}
36		if len(done) != 5 {
37			t.Fatalf("done = %v", done)
38		}
39	}
40	
41	func TestEnqueueWhenFull(t *testing.T) {
42		r := NewRunner(1, 1, nil) // not started: nothing takes jobs off the queue
43		job := Job{Name: "x", Run: func(context.Context) error { return nil }}
44		if err := r.Enqueue(job); err != nil {
45			t.Fatal(err)
46		}
47		if err := r.Enqueue(job); !errors.Is(err, ErrQueueFull) {
48			t.Fatalf("err = %v, want ErrQueueFull", err)
49		}
50	}
