}

// Enqueue adds a job to the queue without waiting. It returns ErrQueueFull when the queue has no room
// and ErrStopped once Shutdown has been called.
func (r *Runner) Enqueue(j Job) error {
	r.mu.Lock()
	defer r.mu.Unlock()
	if r.closed {
		return ErrStopped
	}
	if len(r.pending) >= r.queueSize {
		return ErrQueueFull
	}
	r.seq++
	r.pending = append(r.pending, item{seq: r.seq, job: j})
	r.cond.Signal()
	return nil
}

// Shutdown stops the runner. From the moment it is called, Enqueue returns ErrStopped and no queued job starts.
// It waits for the running jobs to finish. If ctx ends first, it cancels the context of the running jobs,
// waits for them to return, and returns ctx.Err(). A call after the first returns nil at once.
func (r *Runner) Shutdown(ctx context.Context) error {
	r.mu.Lock()
	if r.closed {
		r.mu.Unlock()
		return nil
	}
	r.closed = true
	r.unstarted = r.pending
	r.pending = nil
	r.cond.Broadcast()
	r.mu.Unlock()

	done := make(chan struct{})
	go func() {
		r.running.Wait()
		close(done)
	}()
	select {
	case <-done:
		r.cancel()
		return nil
	case <-ctx.Done():
		r.cancel()
		select {
		case <-done:
			return nil
		default:
		}
		<-done
		return ctx.Err()
	}
}

// Pending returns the jobs that still need to run, in the order they were enqueued. Before Shutdown these are
// the queued jobs not started yet. After Shutdown they are the jobs that never started, followed by the jobs
// that Shutdown cancelled and that returned an error. The caller saves them.
func (r *Runner) Pending() []Job {
	r.mu.Lock()
	defer r.mu.Unlock()
	if !r.closed {
		return jobsOf(r.pending)
	}
	interrupted := slices.Clone(r.interrupted)
	slices.SortFunc(interrupted, func(a, b item) int {
		switch {
		case a.seq < b.seq:
			return -1
		case a.seq > b.seq:
			return 1
		}
		return 0
	})
	return jobsOf(append(slices.Clone(r.unstarted), interrupted...))
}

func jobsOf(items []item) []Job {
	jobs := make([]Job, 0, len(items))
	for _, it := range items {
		jobs = append(jobs, it.job)
	}
	return jobs
}

// Stop stops the runner like Shutdown, waiting at most 30 seconds for the running jobs.
func (r *Runner) Stop() {
	ctx, cancel := context.WithTimeout(context.Background(), stopTimeout)
	defer cancel()
	if err := r.Shutdown(ctx); err != nil {
		r.log.Error("stop", "err", err)
	}
}

// Package jobs runs background work (renewals, webhook deliveries, emails) on a fixed number of workers.
package jobs

import (
	"context"
	"errors"
	"io"
	"log/slog"
	"slices"
	"sync"
	"time"
)

// Job is one piece of background work.
type Job struct {
	Name string
	Run  func(ctx context.Context) error
}

// ErrQueueFull is returned by Enqueue when the queue has no room.
var ErrQueueFull = errors.New("the job queue is full")

// ErrStopped is returned by Enqueue once Shutdown or Stop has been called.
var ErrStopped = errors.New("the job runner is stopped")

// stopTimeout is how long Stop waits for running jobs before cancelling them.
const stopTimeout = 30 * time.Second

// item is a queued job with its enqueue order, so that Pending can report jobs in that order.
type item struct {
	seq uint64
	job Job
}

// Runner runs jobs on its workers.
type Runner struct {
	workers   int
	queueSize int
	log       *slog.Logger

	// ctx is passed to every job. Shutdown cancels it when the running jobs must stop.
	ctx    context.Context
	cancel context.CancelFunc
	// running counts the worker goroutines.
	running sync.WaitGroup

	mu      sync.Mutex
	cond    *sync.Cond
	seq     uint64
	closed  bool
	pending []item // queued and not started
	// unstarted holds the jobs Shutdown took from pending; they will never run.
	unstarted []item
	// interrupted holds the jobs that Shutdown cancelled and that returned an error.
	interrupted []item
}

// NewRunner returns a runner with workers workers and room for queueSize waiting jobs. A nil log discards.
func NewRunner(workers, queueSize int, log *slog.Logger) *Runner {
	if workers < 1 {
		workers = 1
	}
	if log == nil {
		log = slog.New(slog.NewTextHandler(io.Discard, nil))
	}
	ctx, cancel := context.WithCancel(context.Background())
	r := &Runner{workers: workers, queueSize: queueSize, log: log, ctx: ctx, cancel: cancel}
	r.cond = sync.NewCond(&r.mu)
	return r
}

// Start starts the workers. It does nothing once Shutdown has been called.
func (r *Runner) Start() {
	r.mu.Lock()
	defer r.mu.Unlock()
	if r.closed {
		return
	}
	r.running.Add(r.workers)
	for i := 0; i < r.workers; i++ {
		go r.work()
	}
}

func (r *Runner) work() {
	defer r.running.Done()
	for {
		it, ok := r.next()
		if !ok {
			return
		}
		panicked, err := r.exec(it.job)
		switch {
		case panicked:
			// The worker has logged the panic; the job is not run again.
		case err != nil && r.ctx.Err() != nil:
			r.log.Info("job interrupted by shutdown", "job", it.job.Name, "err", err)
			r.mu.Lock()
			r.interrupted = append(r.interrupted, it)
			r.mu.Unlock()
		case err != nil:
			r.log.Error("job failed", "job", it.job.Name, "err", err)
		}
	}
}

// next takes the oldest queued job. It returns false once the runner is shut down, so no job starts after that.
func (r *Runner) next() (item, bool) {
	r.mu.Lock()
	defer r.mu.Unlock()
	for len(r.pending) == 0 && !r.closed {
		r.cond.Wait()
	}
	if r.closed {
		return item{}, false
	}
	it := r.pending[0]
	r.pending = r.pending[1:]
	return it, true
}

// exec runs one job and recovers its panic. It reports whether the job panicked.
func (r *Runner) exec(j Job) (panicked bool, err error) {
	defer func() {
		if p := recover(); p != nil {
			r.log.Error("job panicked", "job", j.Name, "panic", p)
			panicked = true
		}
	}()
	return false, j.Run(r.ctx)
}

// Enqueue adds a job to the queue without waiting. It returns ErrQueueFull when the queue has no room
// and ErrStopped once Shutdown has been called.
func (r *Runner) Enqueue(j Job) error {
	r.mu.Lock()
	defer r.mu.Unlock()
	if r.closed {
		return ErrStopped
	}
	if len(r.pending) >= r.queueSize {
		return ErrQueueFull
	}
	r.seq++
	r.pending = append(r.pending, item{seq: r.seq, job: j})
	r.cond.Signal()
	return nil
}

// Shutdown stops the runner. From the moment it is called, Enqueue returns ErrStopped and no queued job starts.
// It waits for the running jobs to finish. If ctx ends first, it cancels the context of the running jobs,
// waits for them to return, and returns ctx.Err(). A call after the first returns nil at once.
func (r *Runner) Shutdown(ctx context.Context) error {
	r.mu.Lock()
	if r.closed {
		r.mu.Unlock()
		return nil
	}
	r.closed = true
	r.unstarted = r.pending
	r.pending = nil
	r.cond.Broadcast()
	r.mu.Unlock()

	done := make(chan struct{})
	go func() {
		r.running.Wait()
		close(done)
	}()
	select {
	case <-done:
		r.cancel()
		return nil
	case <-ctx.Done():
		r.cancel()
		select {
		case <-done:
			return nil
		default:
		}
		<-done
		return ctx.Err()
	}
}

// Pending returns the jobs that still need to run, in the order they were enqueued. Before Shutdown these are
// the queued jobs not started yet. After Shutdown they are the jobs that never started, followed by the jobs
// that Shutdown cancelled and that returned an error. The caller saves them.
func (r *Runner) Pending() []Job {
	r.mu.Lock()
	defer r.mu.Unlock()
	if !r.closed {
		return jobsOf(r.pending)
	}
	interrupted := slices.Clone(r.interrupted)
	slices.SortFunc(interrupted, func(a, b item) int {
		switch {
		case a.seq < b.seq:
			return -1
		case a.seq > b.seq:
			return 1
		}
		return 0
	})
	return jobsOf(append(slices.Clone(r.unstarted), interrupted...))
}

func jobsOf(items []item) []Job {
	jobs := make([]Job, 0, len(items))
	for _, it := range items {
		jobs = append(jobs, it.job)
	}
	return jobs
}

// Stop stops the runner like Shutdown, waiting at most 30 seconds for the running jobs.
func (r *Runner) Stop() {
	ctx, cancel := context.WithTimeout(context.Background(), stopTimeout)
	defer cancel()
	if err := r.Shutdown(ctx); err != nil {
		r.log.Error("stop", "err", err)
	}
}

