// waitClosed waits until Shutdown has closed the runner to new jobs.
func waitClosed(t *testing.T, r *Runner) {
	t.Helper()
	deadline := time.Now().Add(5 * time.Second)
	for {
		r.mu.Lock()
		closed := r.closed
		r.mu.Unlock()
		if closed {
			return
		}
		if time.Now().After(deadline) {
			t.Fatal("runner did not close")
		}
		time.Sleep(time.Millisecond)
	}
}

func TestPendingBeforeShutdownIsQueueInOrder(t *testing.T) {
	r := NewRunner(1, 10, nil) // not started
	for _, name := range []string{"a", "b", "c"} {
		if err := r.Enqueue(Job{Name: name, Run: func(context.Context) error { return nil }}); err != nil {
			t.Fatal(err)
		}
	}
	if got := names(r.Pending()); !slices.Equal(got, []string{"a", "b", "c"}) {
		t.Fatalf("Pending = %v, want [a b c]", got)
	}
}

func TestEnqueueAfterShutdownReturnsErrStopped(t *testing.T) {
	r := NewRunner(1, 1, nil)
	r.Start()
	if err := r.Shutdown(context.Background()); err != nil {
		t.Fatal(err)
	}
	job := Job{Name: "late", Run: func(context.Context) error {
		t.Error("late job ran")
		return nil
	}}
	if err := r.Enqueue(job); !errors.Is(err, ErrStopped) {
		t.Fatalf("err = %v, want ErrStopped", err)
	}
	if got := r.Pending(); len(got) != 0 {
		t.Fatalf("Pending = %v, want none", names(got))
	}
}

func TestShutdownDoesNotStartQueuedJobs(t *testing.T) {
	r := NewRunner(1, 10, nil)
	r.Start()
	started := make(chan struct{})
	release := make(chan struct{})
	if err := r.Enqueue(Job{Name: "running", Run: func(context.Context) error {
		close(started)
		<-release
		return nil
	}}); err != nil {
		t.Fatal(err)
	}
	if err := r.Enqueue(Job{Name: "queued", Run: func(context.Context) error {
		t.Error("queued job started after Shutdown")
		return nil
	}}); err != nil {
		t.Fatal(err)
	}
	<-started

	shutdown := make(chan error, 1)
	go func() { shutdown <- r.Shutdown(context.Background()) }()
	waitClosed(t, r)
	close(release)

	select {
	case err := <-shutdown:
		if err != nil {
			t.Fatalf("Shutdown = %v, want nil", err)
		}
	case <-time.After(5 * time.Second):
		t.Fatal("Shutdown did not return")
	}
	if got := names(r.Pending()); !slices.Equal(got, []string{"queued"}) {
		t.Fatalf("Pending = %v, want [queued]", got)
	}
}

func TestShutdownTimeoutCancelsRunningJobs(t *testing.T) {
	r := NewRunner(2, 10, nil)
	r.Start()
	started := make(chan struct{}, 2)
	block := func(ctx context.Context) error {
		started <- struct{}{}
		<-ctx.Done()
		return ctx.Err()
	}
	for _, j := range []Job{
		{Name: "slow", Run: block},
		{Name: "quiet", Run: func(ctx context.Context) error {
			started <- struct{}{}
			<-ctx.Done()
			return nil // finished when cancelled: not pending
		}},
		{Name: "waiting", Run: func(context.Context) error { t.Error("waiting job ran"); return nil }},
		{Name: "later", Run: func(context.Context) error { t.Error("later job ran"); return nil }},
	} {
		if err := r.Enqueue(j); err != nil {
			t.Fatal(err)
		}
	}
	<-started
	<-started

	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Millisecond)
	defer cancel()
	if err := r.Shutdown(ctx); !errors.Is(err, context.DeadlineExceeded) {
		t.Fatalf("Shutdown = %v, want DeadlineExceeded", err)
	}
	if got := names(r.Pending()); !slices.Equal(got, []string{"waiting", "later", "slow"}) {
		t.Fatalf("Pending = %v, want [waiting later slow]", got)
	}
}

func TestShutdownWaitsForRunningJobs(t *testing.T) {
	r := NewRunner(1, 10, nil)
	r.Start()
	var finished atomic.Bool
	if err := r.Enqueue(Job{Name: "slow", Run: func(context.Context) error {
		time.Sleep(20 * time.Millisecond)
		finished.Store(true)
		return nil
	}}); err != nil {
		t.Fatal(err)
	}
	time.Sleep(5 * time.Millisecond) // let the job start
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	if err := r.Shutdown(ctx); err != nil {
		t.Fatalf("Shutdown = %v, want nil", err)
	}
	if !finished.Load() {
		t.Fatal("Shutdown returned before the running job finished")
	}
	if got := r.Pending(); len(got) != 0 {
		t.Fatalf("Pending = %v, want none", names(got))
	}
}

func TestPanickingJobIsRecovered(t *testing.T) {
	r := NewRunner(1, 10, nil)
	r.Start()
	ran := make(chan struct{})
	if err := r.Enqueue(Job{Name: "boom", Run: func(context.Context) error { panic("boom") }}); err != nil {
		t.Fatal(err)
	}
	if err := r.Enqueue(Job{Name: "after", Run: func(context.Context) error {
		close(ran)
		return nil
	}}); err != nil {
		t.Fatal(err)
	}
	select {
	case <-ran:
	case <-time.After(5 * time.Second):
		t.Fatal("job after the panic did not run")
	}
	if err := r.Shutdown(context.Background()); err != nil {
		t.Fatal(err)
	}
	if got := r.Pending(); len(got) != 0 {
		t.Fatalf("Pending = %v, want none", names(got))
	}
}

func TestSecondShutdownAndStopReturnAtOnce(t *testing.T) {
	r := NewRunner(1, 10, nil)
	r.Start()
	started := make(chan struct{})
	release := make(chan struct{})
	if err := r.Enqueue(Job{Name: "running", Run: func(context.Context) error {
		close(started)
		<-release
		return nil
	}}); err != nil {
		t.Fatal(err)
	}
	<-started

	first := make(chan error, 1)
	go func() { first <- r.Shutdown(context.Background()) }()
	waitClosed(t, r)

	second := make(chan error, 1)
	go func() { second <- r.Shutdown(context.Background()) }()
	select {
	case err := <-second:
		if err != nil {
			t.Fatalf("second Shutdown = %v, want nil", err)
		}
	case <-time.After(5 * time.Second):
		t.Fatal("second Shutdown waited for the first")
	}

	close(release)
	if err := <-first; err != nil {
		t.Fatalf("first Shutdown = %v, want nil", err)
	}

	stopped := make(chan struct{})
	go func() { r.Stop(); close(stopped) }()
	select {
	case <-stopped:
	case <-time.After(5 * time.Second):
		t.Fatal("Stop after Shutdown did not return at once")
	}
}
